 const imageService=useMemo(()=>{const match=(p:Pin,v:string)=>[p.title,p.description,p.category,p.style,...p.tags,...p.moods].join(' ').toLowerCase().includes(v.toLowerCase());const related=(id:string)=>{const p=all.find(x=>x.id===id);return p?all.filter(x=>x.id!==id).sort((a,b)=>score(b,p)-score(a,p)):all};function score(a:Pin,p:Pin){return Number(a.category===p.category)*5+Number(a.dominantColor===p.dominantColor)*2+Number(a.style===p.style)*2+Number(a.creator===p.creator)+a.tags.filter(x=>p.tags.includes(x)).length};return {mode:'LOCAL',searchImages:(q:string)=>all.filter(p=>match(p,q)),getTrendingImages:()=>all.filter(p=>p.trending),getExploreImages:()=>all,getCategoryImages:(c:string)=>all.filter(p=>p.category===c),getRelatedImages:related,getSimilarImages:related,getFeaturedImages:()=>all.filter(p=>p.featured),getColorImages:(c:string)=>all.filter(p=>p.dominantColor===c),getMoodImages:(m:string)=>all.filter(p=>p.moods.includes(m))}},[all]);
